export interface ConnectorConfig {
  /** Pipedrive API token with write permissions. */
  pipedriveApiToken: string
  /** Mapping of logical field names to Typeform field IDs. */
  fieldIds: {
    firstName: string
    lastName: string
    email: string
    company: string
    phone: string
    price: string
    title: string
  }
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      number?: number
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface ConnectorResult {
  organizationId: number
  personId: number
  dealId: number
}

function extractAnswer(
  answers: TypeformWebhookPayload['form_response']['answers'],
  fieldId: string
): string | number | undefined {
  const answer = answers.find((a) => a.field.id === fieldId)
  if (!answer) return undefined
  if (answer.type === 'email') return answer.email
  if (answer.type === 'number') return answer.number
  return answer.text
}

function buildFullName(firstName: string | undefined, lastName: string | undefined): string {
  const parts = [firstName, lastName].filter((p): p is string => typeof p === 'string' && p.length > 0)
  return parts.join(' ') || 'Unknown'
}

async function pipedrivePost<T>(
  url: string,
  body: unknown,
  apiToken: string,
  fetchFn: typeof fetch
): Promise<T> {
  const separator = url.includes('?') ? '&' : '?'
  const fullUrl = `${url}${separator}api_token=${encodeURIComponent(apiToken)}`
  const response = await fetchFn(fullUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${url}`)
  }
  return response.json() as Promise<T>
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const fetchFn = config.fetch ?? fetch

  if (payload.event_type !== 'form_response') {
    throw new Error('Invalid event_type: expected form_response')
  }

  const { answers } = payload.form_response
  const { fieldIds } = config

  const firstName = extractAnswer(answers, fieldIds.firstName) as string | undefined
  const lastName = extractAnswer(answers, fieldIds.lastName) as string | undefined
  const email = extractAnswer(answers, fieldIds.email) as string | undefined
  const company = extractAnswer(answers, fieldIds.company) as string | undefined
  const phone = extractAnswer(answers, fieldIds.phone) as string | undefined
  const price = extractAnswer(answers, fieldIds.price) as number | undefined
  const title = extractAnswer(answers, fieldIds.title) as string | undefined

  if (!company) {
    throw new Error('Missing required field: company')
  }
  if (!firstName && !lastName) {
    throw new Error('Missing required field: first_name or last_name')
  }
  if (price === undefined) {
    throw new Error('Missing required field: price')
  }
  if (!title) {
    throw new Error('Missing required field: title')
  }

  // 1. Create organization
  const orgResponse = await pipedrivePost<{ data: { id: number } }>(
    'https://api.pipedrive.com/v1/organizations',
    { name: company },
    config.pipedriveApiToken,
    fetchFn
  )
  const organizationId = orgResponse.data.id

  // 2. Create person
  const personResponse = await pipedrivePost<{ data: { id: number } }>(
    'https://api.pipedrive.com/v1/persons',
    {
      name: buildFullName(firstName, lastName),
      email,
      phone,
      org_id: organizationId,
    },
    config.pipedriveApiToken,
    fetchFn
  )
  const personId = personResponse.data.id

  // 3. Create deal
  const dealResponse = await pipedrivePost<{ data: { id: number } }>(
    'https://api.pipedrive.com/v1/deals',
    {
      title,
      value: price,
      person_id: personId,
    },
    config.pipedriveApiToken,
    fetchFn
  )
  const dealId = dealResponse.data.id

  return { organizationId, personId, dealId }
}

import { describe, it, expect, vi } from 'vitest'
