    expect(result).toEqual({ organizationId: 12345, personId: 67890, dealId: 54321 })
    expect(calls).toHaveLength(3)
    expect(calls[0].url).toBe('https://api.pipedrive.com/v1/organizations?api_token=test-token')
    expect(calls[1].url).toBe('https://api.pipedrive.com/v1/persons?api_token=test-token')
    expect(calls[2].url).toBe('https://api.pipedrive.com/v1/deals?api_token=test-token')
  })

