  it('uses only last_name when first_name is missing', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url.includes('/persons')) {
